```javascript
const readline = require('readline').createInterface({
  input: process.stdin,
  output: process.stdout
});

readline.on('line', (line) => {
  const N = BigInt(line.trim());
  const result = (2n * N * N + 2n * N - 1n);
  console.log(result.toString());
  readline.close();
});
```

